// Mem_Firewall_apb: APB4 register wrapper around Mem_Firewall_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Mem_Firewall.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Mem_Firewall.md
// ============================================================================
module Mem_Firewall_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [3:0] s_awid,
  input logic [31:0] s_awaddr,
  input logic [7:0] s_awlen,
  input logic [2:0] s_awsize,
  input logic [1:0] s_awburst,
  input logic [2:0] s_awprot,
  input logic s_awvalid,
  output logic s_awready,
  input logic [31:0] s_wdata,
  input logic [3:0] s_wstrb,
  input logic s_wlast,
  input logic s_wvalid,
  output logic s_wready,
  output logic [3:0] s_bid,
  output logic [1:0] s_bresp,
  output logic s_bvalid,
  input logic s_bready,
  input logic [3:0] s_arid,
  input logic [31:0] s_araddr,
  input logic [7:0] s_arlen,
  input logic [2:0] s_arsize,
  input logic [1:0] s_arburst,
  input logic [2:0] s_arprot,
  input logic s_arvalid,
  output logic s_arready,
  output logic [3:0] s_rid,
  output logic [31:0] s_rdata,
  output logic [1:0] s_rresp,
  output logic s_rlast,
  output logic s_rvalid,
  input logic s_rready,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C070100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [21:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd22) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic [31:0]   c_rgn0_base;
  logic [31:0]   c_rgn0_limit;
  logic [3:0]    c_rgn0_attr;
  logic [31:0]   c_rgn1_base;
  logic [31:0]   c_rgn1_limit;
  logic [3:0]    c_rgn1_attr;
  logic [31:0]   c_rgn2_base;
  logic [31:0]   c_rgn2_limit;
  logic [3:0]    c_rgn2_attr;
  logic [31:0]   c_rgn3_base;
  logic [31:0]   c_rgn3_limit;
  logic [3:0]    c_rgn3_attr;
  logic          c_fault_clr;
  logic [7:0]    c_fault_info;
  logic [31:0]   c_fault_addr;
  logic [15:0]   c_denied_cnt;
  logic          c_fault;
  Mem_Firewall_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .enable(c_enable),
    .rgn0_base(c_rgn0_base),
    .rgn0_limit(c_rgn0_limit),
    .rgn0_attr(c_rgn0_attr),
    .rgn1_base(c_rgn1_base),
    .rgn1_limit(c_rgn1_limit),
    .rgn1_attr(c_rgn1_attr),
    .rgn2_base(c_rgn2_base),
    .rgn2_limit(c_rgn2_limit),
    .rgn2_attr(c_rgn2_attr),
    .rgn3_base(c_rgn3_base),
    .rgn3_limit(c_rgn3_limit),
    .rgn3_attr(c_rgn3_attr),
    .fault_clr(c_fault_clr),
    .fault_info(c_fault_info),
    .fault_addr(c_fault_addr),
    .denied_cnt(c_denied_cnt),
    .fault(c_fault),
    .s_awid(s_awid),
    .s_awaddr(s_awaddr),
    .s_awlen(s_awlen),
    .s_awsize(s_awsize),
    .s_awburst(s_awburst),
    .s_awprot(s_awprot),
    .s_awvalid(s_awvalid),
    .s_awready(s_awready),
    .s_wdata(s_wdata),
    .s_wstrb(s_wstrb),
    .s_wlast(s_wlast),
    .s_wvalid(s_wvalid),
    .s_wready(s_wready),
    .s_bid(s_bid),
    .s_bresp(s_bresp),
    .s_bvalid(s_bvalid),
    .s_bready(s_bready),
    .s_arid(s_arid),
    .s_araddr(s_araddr),
    .s_arlen(s_arlen),
    .s_arsize(s_arsize),
    .s_arburst(s_arburst),
    .s_arprot(s_arprot),
    .s_arvalid(s_arvalid),
    .s_arready(s_arready),
    .s_rid(s_rid),
    .s_rdata(s_rdata),
    .s_rresp(s_rresp),
    .s_rlast(s_rlast),
    .s_rvalid(s_rvalid),
    .s_rready(s_rready),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_RGN0_BASE;   // 12'h018 RGN0_BASE
  logic [31:0] r_RGN0_LIMIT;   // 12'h01C RGN0_LIMIT
  logic [3:0] r_RGN0_ATTR;   // 12'h020 RGN0_ATTR
  logic [31:0] r_RGN1_BASE;   // 12'h024 RGN1_BASE
  logic [31:0] r_RGN1_LIMIT;   // 12'h028 RGN1_LIMIT
  logic [3:0] r_RGN1_ATTR;   // 12'h02C RGN1_ATTR
  logic [31:0] r_RGN2_BASE;   // 12'h030 RGN2_BASE
  logic [31:0] r_RGN2_LIMIT;   // 12'h034 RGN2_LIMIT
  logic [3:0] r_RGN2_ATTR;   // 12'h038 RGN2_ATTR
  logic [31:0] r_RGN3_BASE;   // 12'h03C RGN3_BASE
  logic [31:0] r_RGN3_LIMIT;   // 12'h040 RGN3_LIMIT
  logic [3:0] r_RGN3_ATTR;   // 12'h044 RGN3_ATTR
  logic [0:0] p_CMD;   // 12'h048 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 1'h0;
      r_RGN0_BASE <= 32'h0;
      r_RGN0_LIMIT <= 32'h0;
      r_RGN0_ATTR <= 4'h0;
      r_RGN1_BASE <= 32'h0;
      r_RGN1_LIMIT <= 32'h0;
      r_RGN1_ATTR <= 4'h0;
      r_RGN2_BASE <= 32'h0;
      r_RGN2_LIMIT <= 32'h0;
      r_RGN2_ATTR <= 4'h0;
      r_RGN3_BASE <= 32'h0;
      r_RGN3_LIMIT <= 32'h0;
      r_RGN3_ATTR <= 4'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[6]) r_RGN0_BASE <= (r_RGN0_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_RGN0_LIMIT <= (r_RGN0_LIMIT & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_RGN0_ATTR <= (r_RGN0_ATTR & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[9]) r_RGN1_BASE <= (r_RGN1_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_RGN1_LIMIT <= (r_RGN1_LIMIT & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_RGN1_ATTR <= (r_RGN1_ATTR & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[12]) r_RGN2_BASE <= (r_RGN2_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_RGN2_LIMIT <= (r_RGN2_LIMIT & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_RGN2_ATTR <= (r_RGN2_ATTR & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[15]) r_RGN3_BASE <= (r_RGN3_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[16]) r_RGN3_LIMIT <= (r_RGN3_LIMIT & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_RGN3_ATTR <= (r_RGN3_ATTR & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      p_CMD <= (wr && hit[18]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL;
  assign c_rgn0_base = r_RGN0_BASE[31:0];
  assign c_rgn0_limit = r_RGN0_LIMIT[31:0];
  assign c_rgn0_attr = r_RGN0_ATTR[3:0];
  assign c_rgn1_base = r_RGN1_BASE[31:0];
  assign c_rgn1_limit = r_RGN1_LIMIT[31:0];
  assign c_rgn1_attr = r_RGN1_ATTR[3:0];
  assign c_rgn2_base = r_RGN2_BASE[31:0];
  assign c_rgn2_limit = r_RGN2_LIMIT[31:0];
  assign c_rgn2_attr = r_RGN2_ATTR[3:0];
  assign c_rgn3_base = r_RGN3_BASE[31:0];
  assign c_rgn3_limit = r_RGN3_LIMIT[31:0];
  assign c_rgn3_attr = r_RGN3_ATTR[3:0];
  assign c_fault_clr = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_fault;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_RGN0_BASE);
      10'd7: apb_rdata = 32'(r_RGN0_LIMIT);
      10'd8: apb_rdata = 32'(r_RGN0_ATTR);
      10'd9: apb_rdata = 32'(r_RGN1_BASE);
      10'd10: apb_rdata = 32'(r_RGN1_LIMIT);
      10'd11: apb_rdata = 32'(r_RGN1_ATTR);
      10'd12: apb_rdata = 32'(r_RGN2_BASE);
      10'd13: apb_rdata = 32'(r_RGN2_LIMIT);
      10'd14: apb_rdata = 32'(r_RGN2_ATTR);
      10'd15: apb_rdata = 32'(r_RGN3_BASE);
      10'd16: apb_rdata = 32'(r_RGN3_LIMIT);
      10'd17: apb_rdata = 32'(r_RGN3_ATTR);
      10'd19: apb_rdata = 32'({c_fault_info});
      10'd20: apb_rdata = 32'({c_fault_addr});
      10'd21: apb_rdata = 32'({c_denied_cnt});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
